/**
 * Merge overlapping intervals.
 *
 * Two intervals overlap if one starts before or at the point the other ends.
 * Touching intervals (e.g. [1,3] and [3,5]) are merged.
 *
 * @param {number[][]} intervals - Array of [start, end] pairs (may be unsorted)
 * @returns {number[][]} Merged, non-overlapping intervals sorted by start value
 */
function mergeIntervals(intervals) {
  if (intervals.length === 0) return [];

  // Sort by start value, then by end value for deterministic ordering
  const sorted = [...intervals].sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [sorted[0].slice()];

  for (let i = 1; i < sorted.length; i++) {
    const [start, end] = sorted[i];
    const last = merged[merged.length - 1];

    // Touching or overlapping: merge
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}

module.exports = { mergeIntervals };

