node -e "
const { mergeIntervals } = require('./bench/sandbox/merge-intervals-ht.js');

// Test cases
console.log('Empty:', JSON.stringify(mergeIntervals([])));
console.log('Single:', JSON.stringify(mergeIntervals([[1, 3]])));
console.log('Touching:', JSON.stringify(mergeIntervals([[1, 3], [3, 5]])));
console.log('Overlapping:', JSON.stringify(mergeIntervals([[1, 4], [2, 5]])));
console.log('Contained:', JSON.stringify(mergeIntervals([[1, 10], [2, 3]])));
console.log('Unsorted:', JSON.stringify(mergeIntervals([[5, 7], [1, 3], [2, 4]])));
console.log('Negative:', JSON.stringify(mergeIntervals([[-3, -1], [-2, 0]])));
console.log('No overlap:', JSON.stringify(mergeIntervals([[1, 2], [4, 6]])));
console.log('All merge:', JSON.stringify(mergeIntervals([[1, 5], [2, 6], [3, 7]])));
console.log('Mixed:', JSON.stringify(mergeIntervals([[1, 3], [0, 2], [4, 6], [8, 10], [5, 7], [9, 11]])));
